from abc import ABC, abstractmethod

# 1. Strategy Interface
class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount): pass

# 2. Concrete Strategies - each is one algorithm
class CreditCardStrategy(PaymentStrategy):
    def __init__(self, card_number):
        self.card_number = card_number

    def pay(self, amount):
        print(f"Charging ${amount} to card ending {self.card_number[-4:]}")

class PayPalStrategy(PaymentStrategy):
    def __init__(self, email):
        self.email = email

    def pay(self, amount):
        print(f"Paying ${amount} via PayPal account {self.email}")

class UPIStrategy(PaymentStrategy):
    def __init__(self, upi_id):
        self.upi_id = upi_id

    def pay(self, amount):
        print(f"Paying ${amount} using UPI ID {self.upi_id}")

# 3. Context - doesn't care which strategy it uses
class PaymentProcessor:
    def __init__(self, strategy: PaymentStrategy):
        self.strategy = strategy

    def set_strategy(self, strategy: PaymentStrategy):
        """This is the key: swap strategy at runtime"""
        self.strategy = strategy

    def checkout(self, amount):
        # Delegate the work to the strategy
        self.strategy.pay(amount)

# Usage: switch behavior at runtime
order_amount = 1200
processor = PaymentProcessor(CreditCardStrategy("1234-5678-9012-3456"))
processor.checkout(order_amount)  # Charging $1200 to card ending 3456

# User changes mind, picks PayPal instead
processor.set_strategy(PayPalStrategy("user@example.com"))
processor.checkout(order_amount)  # Paying $1200 via PayPal account user@example.com
